    def __str__(self):
        ret = ''
        for row in self.board:
            for space in row:
                ret += space + ' '
            ret += '\n'
        return ret

    def __lt__(self, other):
        return self.board < other.board

    def __eq__(self, other):
        return self.board == other.board

    def __hash__(self):
        ret = ""
        for row in self.board:
            for value in row:
                if value == " ":
                    ret += "0"
                else:
                    ret += value
        return int(ret)

    def solved(self):
        if self.__hash__() == 123456780:
            return True
        else:
            return False

    def manhattan_distance(self, x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    def heuristic(self):

        solution_board = [
            ['1', '2', '3'],
            ['4', '5', '6'],
            ['7', '8', ' '],
        ]

        positions = {}

        for i in range(0, 3):
            for j in range(0, 3):
                positions[solution_board[i][j]] = (i, j)
        # print(positions)
        # print(positions[self.board[0][2]][0])

        sumofmd = 0
        for i in range(0, 3):
            for j in range(0, 3):
                if self.board[i][j] == " ":
                    continue
                sumofmd += self.manhattan_distance(
                    i,
                    j,
                    positions[self.board[i][j]][0],
                    positions[self.board[i][j]][1],
                )
        return sumofmd

    def is_solvable(self):
        # A valid 3-by-3 board reaches the goal exactly when inversion parity is even.
        values = [tile for row in self.board for tile in row if tile != " "]
        inversions = sum(left > right for i, left in enumerate(values)
                         for right in values[i + 1:])
        return inversions % 2 == 0

